import { useCallback, useEffect, useMemo, useReducer, useRef, useState, type ReactNode } from 'react'
import { currentSample, fishIdForSample, initialSession, reducer, sampleOrder, weightForSample, type DemoOutcome, type Grade, type Role, type SampleResult, type SampleType, type Screen } from './kioskState'

const DEMO_ADMIN_PIN = '1234'
interface BeforeInstallPromptEvent extends Event { prompt: () => Promise<void>; userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }> }
const capturedEvidence: Partial<Record<SampleType, string>> = {}
const existingGraders = ['Maria Santos', 'Jose Dela Cruz', 'Ana Mae Lim']
const allScreens: Screen[] = ['welcome', 'select-role', 'admin', 'admin-dashboard', 'grader', 'sample', 'association', 'tutorial', 'weight', 'camera', 'review', 'analysis', 'individual-result', 'overview', 'print', 'complete']
const stepForScreen: Partial<Record<Screen, number>> = { camera: 0, review: 0, analysis: 1, 'individual-result': 2, overview: 2, print: 2 }
const pathForScreen = (screen: Screen) => screen === 'welcome' ? '/' : screen === 'select-role' ? '/select-role' : screen === 'admin' || screen === 'admin-dashboard' ? '/admin' : `/kiosk/${screen}`
const screenForPath = (path: string): Screen => { if (path === '/select-role') return 'select-role'; if (path === '/admin') return 'admin'; if (path.startsWith('/kiosk/')) { const candidate = path.replace('/kiosk/', '') as Screen; if (allScreens.includes(candidate)) return candidate } return 'welcome' }

type IconName = 'arrow' | 'back' | 'camera' | 'check' | 'chevron' | 'help' | 'home' | 'lock' | 'play' | 'printer' | 'refresh' | 'scale' | 'shield' | 'spark' | 'tutorial' | 'users' | 'database' | 'settings'
function Icon({ name, size = 24 }: { name: IconName; size?: number }) {
  const common = { width: size, height: size, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const, 'aria-hidden': true }
  switch (name) {
    case 'arrow': return <svg {...common}><path d="M5 12h13" /><path d="m13 6 6 6-6 6" /></svg>
    case 'back': return <svg {...common}><path d="m14.5 5-7 7 7 7" /><path d="M8 12h11" /></svg>
    case 'camera': return <svg {...common}><path d="M4 8.5h3l1.5-2h7L17 8.5h3v10H4z" /><circle cx="12" cy="13.5" r="3.5" /></svg>
    case 'check': return <svg {...common}><path d="m5 12 4.2 4.2L19 6.5" /></svg>
    case 'chevron': return <svg {...common}><path d="m9 5 7 7-7 7" /></svg>
    case 'help': return <svg {...common}><circle cx="12" cy="12" r="9" /><path d="M9.8 9.3a2.3 2.3 0 1 1 3.3 2.1c-.9.4-1.1.9-1.1 1.8" /><path d="M12 16.5h.01" /></svg>
    case 'home': return <svg {...common}><path d="m4 10 8-6 8 6" /><path d="M6 9.5V20h12V9.5" /><path d="M10 20v-5h4v5" /></svg>
    case 'lock': return <svg {...common}><rect x="5" y="10" width="14" height="10" rx="2" /><path d="M8 10V7a4 4 0 0 1 8 0v3" /></svg>
    case 'play': return <svg {...common}><path d="m9 6 9 6-9 6z" fill="currentColor" stroke="none" /></svg>
    case 'printer': return <svg {...common}><path d="M7 9V4h10v5" /><path d="M6 18H4v-7h16v7h-2" /><path d="M7 15h10v5H7z" /><path d="M17 12h.01" /></svg>
    case 'refresh': return <svg {...common}><path d="M20 11a8 8 0 0 0-14.7-4L4 9" /><path d="M4 4v5h5" /><path d="M4 13a8 8 0 0 0 14.7 4L20 15" /><path d="M20 20v-5h-5" /></svg>
    case 'scale': return <svg {...common}><path d="M4 6h16" /><path d="M7 6v12" /><path d="M17 6v12" /><path d="M4 18h16" /><path d="M12 8v8" /><path d="m9 11 3-3 3 3" /></svg>
    case 'shield': return <svg {...common}><path d="M12 3 19 6v5c0 4.5-2.7 8-7 10-4.3-2-7-5.5-7-10V6z" /><path d="m9 12 2 2 4-4" /></svg>
    case 'spark': return <svg {...common}><path d="m12 3 1.3 5.7L19 10l-5.7 1.3L12 17l-1.3-5.7L5 10l5.7-1.3z" /></svg>
    case 'tutorial': return <svg {...common}><circle cx="12" cy="12" r="9" /><path d="M9.7 9.2a2.5 2.5 0 1 1 3.7 2.2c-.9.5-1.4 1-1.4 2" /><path d="M12 16.5h.01" /></svg>
    case 'users': return <svg {...common}><path d="M16 20v-1.5a3.5 3.5 0 0 0-3.5-3.5h-5A3.5 3.5 0 0 0 4 18.5V20" /><circle cx="10" cy="8" r="3" /><path d="M16 11a3 3 0 1 0-1.4-5.6" /><path d="M17 15.2a3.5 3.5 0 0 1 3 3.3V20" /></svg>
    case 'database': return <svg {...common}><ellipse cx="12" cy="5" rx="7" ry="3" /><path d="M5 5v7c0 1.7 3.1 3 7 3s7-1.3 7-3V5" /><path d="M5 12v7c0 1.7 3.1 3 7 3s7-1.3 7-3v-7" /></svg>
    case 'settings': return <svg {...common}><path d="M12 8.2a3.8 3.8 0 1 0 0 7.6 3.8 3.8 0 0 0 0-7.6Z" /><path d="m19.4 15 .1.1a2 2 0 1 1-2.8 2.8l-.1-.1a2 2 0 0 0-3.4 1.4v.2a2 2 0 1 1-4 0v-.2a2 2 0 0 0-3.4-1.4l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a2 2 0 0 0-1.4-3.4h-.2a2 2 0 1 1 0-4h.2a2 2 0 0 0 1.4-3.4l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1A2 2 0 0 0 9.2 1.8v-.2a2 2 0 1 1 4 0v.2a2 2 0 0 0 3.4 1.4l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1A2 2 0 0 0 20.8 9h.2a2 2 0 1 1 0 4h-.2a2 2 0 0 0-1.4 2Z" /></svg>
  }
}

function BrandMark({ compact = false }: { compact?: boolean }) { return <div className={`brand-mark ${compact ? 'brand-mark--compact' : ''}`} aria-label="TunaEye"><span className="brand-symbol" aria-hidden="true"><span /></span><span className="brand-word">Tuna<span>Eye</span></span></div> }
function Button({ children, variant = 'primary', icon, onClick, disabled = false, className = '' }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; icon?: IconName; onClick?: () => void; disabled?: boolean; className?: string }) { return <button type="button" className={`btn btn--${variant} ${className}`} onClick={onClick} disabled={disabled}>{children}{icon && <Icon name={icon} size={23} />}</button> }
function StepRail({ active }: { active: number }) { const steps = ['Capture', 'Analyze', 'Result']; return <div className="step-rail" aria-label={`Workflow progress, ${steps[Math.min(Math.max(active, 0), 2)]} stage`}>{steps.map((step, index) => <div className={`step-rail__item ${index <= active ? 'is-active' : ''}`} key={step}><span className="step-rail__dot">{index < active ? <Icon name="check" size={16} /> : index + 1}</span><span>{step}</span>{index < steps.length - 1 && <i />}</div>)}</div> }
const screenLabels: Partial<Record<Screen, string>> = { 'select-role': 'Choose a role', admin: 'Admin access', 'admin-dashboard': 'Admin console', grader: 'Grader entry', sample: 'Sample selector', association: 'Fish association', tutorial: 'Guided tutorial', weight: 'Weight entry', camera: 'Camera preview', review: 'Check image', analysis: 'Analyzing image', 'individual-result': 'Sample result', overview: 'Results overview', print: 'Print results', complete: 'Session complete' }
function TopBar({ screen, onHome }: { screen: Screen; onHome: () => void }) { const showProgress = Boolean(stepForScreen[screen] !== undefined); return <header className="topbar"><BrandMark compact /><div className="topbar__center"><span className="topbar__eyebrow">TunaEye kiosk</span><span className="topbar__title">{screenLabels[screen] ?? 'Ready for the next sample'}</span></div><div className="topbar__actions"><span className="status-pill"><span className="status-dot" />Device ready</span><button className="icon-button" onClick={onHome} aria-label="Return to home"><Icon name="home" size={24} /></button></div>{showProgress && <div className="topbar__progress"><StepRail active={stepForScreen[screen] ?? 0} /></div>}</header> }
function BottomBar({ onBack, onHelp, primary, primaryLabel, primaryIcon = 'arrow', primaryDisabled = false, secondaryLabel, onSecondary }: { onBack?: () => void; onHelp?: () => void; primary?: () => void; primaryLabel?: string; primaryIcon?: IconName; primaryDisabled?: boolean; secondaryLabel?: string; onSecondary?: () => void }) { return <footer className="bottom-bar"><div className="bottom-bar__left">{onBack && <Button variant="ghost" icon="back" onClick={onBack}>Back</Button>}{onHelp && <Button variant="ghost" icon="help" onClick={onHelp}>Help</Button>}</div><div className="bottom-bar__right">{secondaryLabel && onSecondary && <Button variant="secondary" onClick={onSecondary}>{secondaryLabel}</Button>}{primary && primaryLabel && <Button onClick={primary} icon={primaryIcon} disabled={primaryDisabled}>{primaryLabel}</Button>}</div></footer> }
function SampleArt({ sample, className = '' }: { sample: SampleType; className?: string }) { return <img className={`sample-art ${className}`} src={sample === 'Sashibo core' ? '/assets/sashiboCoreFull.png' : '/assets/tailCutFull.png'} alt={`${sample} reference`} /> }
function EvidenceFrame({ sample = 'Sashibo core', mode = 'camera', frozen = false }: { sample?: SampleType; mode?: 'camera' | 'sample' | 'tray'; frozen?: boolean }) { const image = mode === 'sample' ? capturedEvidence[sample] : undefined; return <div className={`evidence-frame evidence-frame--${mode} ${frozen ? 'is-frozen' : ''}`}><div className="evidence-frame__topline"><span>{mode === 'camera' ? 'Live preview' : mode === 'sample' ? 'Captured camera image' : 'Controlled chamber'}</span><span className="evidence-frame__signal"><span className="status-dot" />{mode === 'camera' ? 'Ready' : 'Saved'}</span></div>{image ? <img className="evidence-frame__capture" src={image} alt={`Captured ${sample}`} /> : <div className="chamber"><div className="chamber__rail chamber__rail--left" /><div className="chamber__rail chamber__rail--right" /><div className="tuna-silhouette"><span className="tuna-silhouette__tail" /><span className="tuna-silhouette__body" /><span className="tuna-silhouette__eye" /></div><div className="target-corners"><i /><i /><i /><i /></div>{mode === 'camera' && <div className="camera-crosshair"><span /></div>}</div>}<div className="evidence-frame__bottomline"><span>{frozen ? `${sample} image held for review` : 'Align within the blue guide'}</span><span className="evidence-frame__time">Top-down view</span></div></div> }
function TutorialModal({ onClose, title = 'Guided tutorial' }: { onClose: () => void; title?: string }) { return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label={title}><div className="modal-card"><div className="modal-card__header"><div><span className="eyebrow">{title}</span><h2>Three quick checks before capture</h2></div><button className="icon-button" aria-label="Close tutorial" onClick={onClose}>×</button></div><div className="tutorial-list"><div><span>01</span><div><strong>Pull the tray out</strong><p>Use the chamber handle and keep the sample surface clean.</p></div></div><div><span>02</span><div><strong>Place the tuna flat</strong><p>Keep the selected sample centered in the blue guide.</p></div></div><div><span>03</span><div><strong>Check the view</strong><p>When the image is clear, press Capture once.</p></div></div></div><Button onClick={onClose} icon="check">Got it</Button></div></div> }
function LegalModal({ kind, onClose }: { kind: 'terms' | 'privacy'; onClose: () => void }) { const privacy = kind === 'privacy'; return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label={privacy ? 'Privacy policy' : 'Terms and conditions'}><div className="modal-card legal-modal"><div className="modal-card__header"><div><span className="eyebrow">TunaEye</span><h2>{privacy ? 'Privacy policy' : 'Terms and conditions'}</h2></div><button className="icon-button" aria-label="Close" onClick={onClose}>×</button></div><p>{privacy ? 'This prototype keeps grader name, sample selections, and demo results in the current browser session only. No real account or biometric data is collected.' : 'Use this kiosk only for trained visual grading work. Demo camera, model, and printer states are simulated until hardware services are connected.'}</p><Button onClick={onClose}>Close</Button></div></div> }

function WelcomeScreen({ onStart, onInstall, onTutorial, installed }: { onStart: () => void; onInstall: () => void; onTutorial: () => void; installed: boolean }) { return <div className="welcome-screen"><div className="welcome-screen__ambient" /><div className="welcome-screen__brand"><BrandMark /><span className="ready-line"><span className="status-dot" />Chamber ready · Offline capable</span></div><div className="welcome-screen__hero"><span className="eyebrow">Yellowfin tuna visual grading</span><h1>Clear evidence.<br /><em>Confident decisions.</em></h1><p>Place one sample at a time. TunaEye checks the image, records the result, and keeps the next step simple.</p><div className="welcome-illustration"><div className="welcome-illustration__ring" /><div className="welcome-illustration__eye" /><div className="welcome-illustration__ray welcome-illustration__ray--one" /><div className="welcome-illustration__ray welcome-illustration__ray--two" /><div className="welcome-illustration__ray welcome-illustration__ray--three" /></div></div><div className="welcome-screen__cta"><div className="welcome-screen__actions"><Button className="btn--hero" onClick={onStart} icon="arrow">Start grading</Button><Button variant="secondary" onClick={onInstall} icon="home" disabled={installed}>{installed ? 'App installed' : 'Install app'}</Button></div><span>Expert grader station · Install for offline kiosk access</span></div><button className="tutorial-fab" onClick={onTutorial}><Icon name="tutorial" size={24} />Guided tutorial</button></div> }
function SelectRoleScreen({ onRole, onTutorial, onBack }: { onRole: (role: Role) => void; onTutorial: () => void; onBack: () => void }) { return <div className="screen-stack screen-stack--role"><div className="role-intro"><span className="eyebrow">TunaEye kiosk</span><h1>Who is using this station?</h1><p>Choose the role that matches your task. Public grading stays one tap away.</p></div><div className="role-actions"><button className="role-button" onClick={() => onRole('admin')}><span className="role-button__icon"><Icon name="shield" size={34} /></span><span><strong>Admin</strong><small>Configuration and records</small></span><Icon name="chevron" size={26} /></button><button className="role-button role-button--primary" onClick={() => onRole('expert')}><span className="role-button__icon"><Icon name="camera" size={34} /></span><span><strong>Expert grader</strong><small>Capture and grade a tuna sample</small></span><Icon name="chevron" size={26} /></button></div><div className="role-bottom"><Button variant="ghost" icon="back" onClick={onBack}>Back</Button><button className="tutorial-fab tutorial-fab--inline" onClick={onTutorial}><Icon name="tutorial" size={22} />Guided tutorial</button></div></div> }
function AdminPinScreen({ value, error, onChange, onContinue, onBack }: { value: string; error: string; onChange: (value: string) => void; onContinue: () => void; onBack: () => void }) { return <div className="screen-stack screen-stack--narrow"><div className="admin-icon"><Icon name="lock" size={32} /></div><span className="eyebrow">Protected area</span><h1>Admin access</h1><p>Enter the station PIN to manage pricing, records, and device settings.</p><label className="pin-label">Station PIN<input autoFocus inputMode="numeric" type="password" value={value} onChange={event => onChange(event.target.value.replace(/\D/g, '').slice(0, 4))} placeholder="••••" maxLength={4} /></label>{error ? <span className="error-text"><Icon name="help" size={16} />{error}</span> : <span className="form-hint"><Icon name="shield" size={16} />Demo gate · PIN is 1234 in this prototype</span>}<BottomBar onBack={onBack} primary={onContinue} primaryLabel="Unlock admin" primaryIcon="lock" primaryDisabled={value.length < 4} /></div> }
function AdminDashboard({ onExit }: { onExit: () => void }) {
  type Section = 'Overview' | 'Records' | 'Price schedule' | 'Expert graders' | 'Devices' | 'Settings'
  const [section, setSection] = useState<Section>('Overview')
  const [query, setQuery] = useState('')
  const [prices, setPrices] = useState<Record<Grade, string>>(() => JSON.parse(localStorage.getItem('tunaeye-prices') ?? '{"A":"420","B":"350","C":"280"}'))
  const [graders, setGraders] = useState(() => JSON.parse(localStorage.getItem('tunaeye-graders') ?? JSON.stringify(existingGraders)) as string[])
  const [newGrader, setNewGrader] = useState('')
  const [diagnostic, setDiagnostic] = useState('Ready to run')
  const [stationName, setStationName] = useState(() => localStorage.getItem('tunaeye-station') ?? 'TunaEye Station 01')
  const records = [{ id: 'TE-261005-014', time: '10:42 AM', grader: 'Maria Santos', sample: 'Sashibo core', fish: 'Fish 1', weight: '82.4 kg', grade: 'A', status: 'Complete' }, { id: 'TE-261005-013', time: '10:18 AM', grader: 'Jose Dela Cruz', sample: 'Tail cut', fish: 'Fish 1', weight: '76.8 kg', grade: 'B', status: 'Complete' }, { id: 'TE-261005-012', time: '9:51 AM', grader: 'Ana Mae Lim', sample: 'Sashibo core', fish: 'Fish 1', weight: '91.2 kg', grade: 'A', status: 'Override' }, { id: 'TE-261005-011', time: '9:23 AM', grader: 'Maria Santos', sample: 'Tail cut', fish: 'Fish 2', weight: '68.5 kg', grade: 'C', status: 'Complete' }]
  const visibleRecords = records.filter(record => Object.values(record).some(value => value.toLowerCase().includes(query.toLowerCase())))
  const nav: { label: Section; icon: IconName }[] = [{ label: 'Overview', icon: 'home' }, { label: 'Records', icon: 'database' }, { label: 'Price schedule', icon: 'scale' }, { label: 'Expert graders', icon: 'users' }, { label: 'Devices', icon: 'camera' }, { label: 'Settings', icon: 'settings' }]
  const savePrices = () => { localStorage.setItem('tunaeye-prices', JSON.stringify(prices)); window.alert('Price schedule saved.') }
  const saveGraders = (next: string[]) => { setGraders(next); localStorage.setItem('tunaeye-graders', JSON.stringify(next)) }
  const runDiagnostics = async () => { setDiagnostic('Testing camera…'); try { const stream = await navigator.mediaDevices.getUserMedia({ video: true }); stream.getTracks().forEach(track => track.stop()); setDiagnostic('All systems operational') } catch { setDiagnostic('Camera permission blocked') } }
  const heading = section === 'Overview' ? 'Good day, Admin.' : section
  return <div className="admin-workspace"><aside className="admin-sidebar"><BrandMark compact /><nav>{nav.map(item => <button key={item.label} className={section === item.label ? 'is-active' : ''} onClick={() => setSection(item.label)}><Icon name={item.icon} size={20} /><span>{item.label}</span></button>)}</nav><div className="admin-sidebar__foot"><span><i className="status-dot" />System online</span><button onClick={onExit}><Icon name="home" size={18} />Exit admin</button></div></aside><section className="admin-content"><header className="admin-content__header"><div><span className="eyebrow">{stationName} · Admin console</span><h1>{heading}</h1><p>{section === 'Overview' ? 'Here is what is happening at your grading station today.' : `Manage ${section.toLowerCase()} for this station.`}</p></div><div className="admin-avatar">AD</div></header>
    {section === 'Overview' && <><div className="admin-metrics"><article><span><Icon name="database" size={22} /></span><small>Sessions today</small><strong>24</strong><em>+12% from yesterday</em></article><article><span><Icon name="scale" size={22} /></span><small>Total fish weight</small><strong>1,842 kg</strong><em>Across 24 records</em></article><article><span><Icon name="spark" size={22} /></span><small>Grade A rate</small><strong>67%</strong><em>16 of 24 samples</em></article><article><span><Icon name="users" size={22} /></span><small>Active graders</small><strong>{graders.length}</strong><em>All profiles available</em></article></div><div className="admin-overview-grid"><article className="admin-chart"><div className="admin-section-title"><div><h2>Weekly grading volume</h2><p>Completed samples during the last seven days</p></div><b>142 total</b></div><div className="bar-chart">{[14,22,18,28,24,31,24].map((value,index) => <div key={index}><span style={{ height: `${value * 3}px` }} /><small>{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][index]}</small></div>)}</div></article><article className="admin-breakdown"><h2>Grade breakdown</h2><div className="grade-ring"><strong>142<small>samples</small></strong></div><div className="grade-legend"><span><i className="grade-a" />Grade A <b>67%</b></span><span><i className="grade-b" />Grade B <b>24%</b></span><span><i className="grade-c" />Grade C <b>9%</b></span></div></article></div><AdminRecords records={records.slice(0, 3)} compact onViewAll={() => setSection('Records')} /></>}
    {section === 'Records' && <><div className="admin-toolbar"><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search record, grader, sample, or grade…" /><Button variant="secondary" icon="printer" onClick={() => window.print()}>Export records</Button></div><AdminRecords records={visibleRecords} /></>}
    {section === 'Price schedule' && <div className="admin-page-card"><div className="admin-section-title"><div><h2>Approved buying prices</h2><p>Set the current rate per kilogram for each tuna grade.</p></div><span className="status-label status-label--valid">Active schedule</span></div><div className="price-editor">{(['A','B','C'] as Grade[]).map(grade => <label key={grade}><span>Grade {grade}<small>{grade === 'A' ? 'Premium quality' : grade === 'B' ? 'Standard quality' : 'Processing quality'}</small></span><div><b>₱</b><input inputMode="decimal" value={prices[grade]} onChange={event => setPrices({ ...prices, [grade]: event.target.value.replace(/[^0-9.]/g, '') })} /><small>per kg</small></div></label>)}</div><div className="admin-card-actions"><span>Last updated today · Values are stored on this device.</span><Button onClick={savePrices} icon="check">Save price schedule</Button></div></div>}
    {section === 'Expert graders' && <div className="admin-page-card"><div className="admin-section-title"><div><h2>Grader profiles</h2><p>Control who can start expert grading sessions.</p></div><b>{graders.length} active</b></div><div className="grader-admin-list">{graders.map((name,index) => <div key={name}><span className="admin-avatar">{name.split(' ').map(part => part[0]).slice(0,2).join('')}</span><span><strong>{name}</strong><small>{index === 0 ? 'Last active 8 minutes ago' : 'Available at this station'}</small></span><span className="status-label status-label--valid">Active</span><button aria-label={`Remove ${name}`} onClick={() => saveGraders(graders.filter(item => item !== name))}>Remove</button></div>)}</div><div className="admin-add-grader"><input value={newGrader} onChange={event => setNewGrader(event.target.value)} placeholder="Enter full name" /><Button icon="users" disabled={!newGrader.trim()} onClick={() => { const name = newGrader.trim(); if (name && !graders.includes(name)) saveGraders([...graders, name]); setNewGrader('') }}>Add grader</Button></div></div>}
    {section === 'Devices' && <div className="admin-page-card"><div className="admin-section-title"><div><h2>Station diagnostics</h2><p>Check the camera, local storage, printer, and connection.</p></div><span className={`status-label ${diagnostic.includes('blocked') ? 'status-label--invalid' : 'status-label--valid'}`}>{diagnostic}</span></div><div className="device-grid"><article><Icon name="camera" size={26} /><span><strong>Capture camera</strong><small>Browser camera permission</small></span><b>Ready</b></article><article><Icon name="database" size={26} /><span><strong>Offline storage</strong><small>PWA cache and local records</small></span><b>Ready</b></article><article><Icon name="printer" size={26} /><span><strong>Receipt printer</strong><small>System print service</small></span><b>Ready</b></article><article><Icon name="refresh" size={26} /><span><strong>Network sync</strong><small>{navigator.onLine ? 'Connected to network' : 'Working offline'}</small></span><b>{navigator.onLine ? 'Online' : 'Offline'}</b></article></div><Button onClick={runDiagnostics} icon="refresh">Run full diagnostics</Button></div>}
    {section === 'Settings' && <div className="admin-page-card settings-form"><div><h2>Station settings</h2><p>Customize this device and its grading workflow.</p></div><label>Station name<input value={stationName} onChange={event => setStationName(event.target.value)} /></label><label>Maximum accepted weight<input value="200 kg" disabled /></label><label className="settings-toggle"><span><strong>Offline mode</strong><small>Keep the PWA available without internet</small></span><input type="checkbox" defaultChecked /></label><label className="settings-toggle"><span><strong>Automatic printing</strong><small>Open print dialog after each completed session</small></span><input type="checkbox" /></label><div className="admin-card-actions"><span>Settings apply to this kiosk only.</span><Button icon="check" onClick={() => { localStorage.setItem('tunaeye-station', stationName); window.alert('Station settings saved.') }}>Save settings</Button></div></div>}
  </section></div>
}
function AdminRecords({ records, compact = false, onViewAll }: { records: { id: string; time: string; grader: string; sample: string; fish: string; weight: string; grade: string; status: string }[]; compact?: boolean; onViewAll?: () => void }) { return <div className="admin-table-card"><div className="admin-section-title"><div><h2>{compact ? 'Recent records' : 'Grading records'}</h2><p>{records.length} session{records.length === 1 ? '' : 's'} shown</p></div>{onViewAll && <button onClick={onViewAll}>View all <Icon name="arrow" size={17} /></button>}</div><div className="admin-table"><div className="admin-table__head"><span>Record</span><span>Grader</span><span>Sample</span><span>Weight</span><span>Grade</span><span>Status</span></div>{records.map(record => <div key={record.id}><span><strong>{record.id}</strong><small>{record.time}</small></span><span>{record.grader}</span><span><strong>{record.sample}</strong><small>{record.fish}</small></span><span>{record.weight}</span><span className={`table-grade table-grade--${record.grade}`}>{record.grade}</span><span className={`status-label ${record.status === 'Override' ? 'status-label--uncertain' : 'status-label--valid'}`}>{record.status}</span></div>)}</div></div> }
function GraderEntryScreen({ name, remember, onName, onRemember, onContinue, onBack, onLegal }: { name: string; remember: boolean; onName: (value: string) => void; onRemember: (value: boolean) => void; onContinue: () => void; onBack: () => void; onLegal: (kind: 'terms' | 'privacy') => void }) { return <div className="screen-stack screen-stack--grader"><div className="grader-entry"><div className="grader-entry__copy"><BrandMark /><span className="eyebrow">Expert grader session</span><h1>Who is grading today?</h1><p>Choose your name or enter it once for this session. No password is required in this prototype.</p></div><div className="grader-entry__form"><label className="field-label">Expert grader name<input autoFocus value={name} onChange={event => onName(event.target.value)} placeholder="Enter or select a name" /></label><div className="grader-profiles">{existingGraders.map(person => <button key={person} className={name === person ? 'is-selected' : ''} onClick={() => onName(person)}>{person}{name === person && <Icon name="check" size={17} />}</button>)}</div><label className="remember-row"><input type="checkbox" checked={remember} onChange={event => onRemember(event.target.checked)} /><span>Remember my name for this session</span></label><div className="legal-links"><button onClick={() => onLegal('terms')}>Terms and Conditions</button><span>·</span><button onClick={() => onLegal('privacy')}>Privacy Policy</button></div></div></div><BottomBar onBack={onBack} primary={onContinue} primaryLabel="Continue" primaryDisabled={!name.trim()} /></div> }

const sampleOptions: { label: string; sample: SampleType; copy: string }[] = [{ label: 'Sashibo core', sample: 'Sashibo core', copy: 'Center sashibo evidence' }, { label: 'Tail cut', sample: 'Tail cut', copy: 'Tail-cut evidence' }]
function SampleScreen({ selected, onSelect, onContinue, onBack }: { selected: SampleType[]; onSelect: (samples: SampleType[]) => void; onContinue: () => void; onBack: () => void }) { const toggle = (sample: SampleType) => onSelect(selected.includes(sample) ? selected.filter(item => item !== sample) : sampleOrder.filter(item => [...selected, sample].includes(item))); return <div className="screen-stack screen-stack--sample-selector"><div className="section-heading"><span className="eyebrow">Step 1 · Sample selector</span><h1>What are you grading?</h1><p>Select either sample or choose both. Each selection stays linked to its own evidence.</p></div><div className="sample-options sample-options--two">{sampleOptions.map(option => { const active = selected.includes(option.sample); return <button key={option.label} className={`sample-card selector-card ${active ? 'is-selected' : ''}`} onClick={() => toggle(option.sample)}><div className="selector-card__art"><SampleArt sample={option.sample} /></div><span className="sample-card__label"><strong>{option.label}</strong><small>{option.copy}</small></span><span className="sample-card__check">{active && <Icon name="check" size={18} />}</span></button> })}</div><div className="selector-note"><Icon name="shield" size={18} />Select both cards to capture both samples.</div><BottomBar onBack={onBack} primary={onContinue} primaryLabel="Continue" primaryDisabled={!selected.length} /></div> }
function AssociationScreen({ samples, sameFish, onSameFish, onContinue, onBack }: { samples: SampleType[]; sameFish: 'same' | 'different' | null; onSameFish: (value: 'same' | 'different') => void; onContinue: () => void; onBack: () => void }) { const single = samples.length === 1; return <div className="screen-stack screen-stack--association"><div className="association-copy"><span className="eyebrow">Step 2 · Fish association</span><h1>{single ? 'This sample is ready to follow one fish.' : 'Are these samples from the same fish?'}</h1><p>{single ? `${samples[0]} will be captured, weighed, graded, and printed as one individual sample.` : 'This keeps the sashibo core and tail cut linked correctly through weight, results, overrides, and printing.'}</p></div>{single ? <div className="single-fish-card"><span className="single-fish-card__icon"><Icon name="check" size={30} /></span><div><strong>One fish · one sample</strong><small>{samples[0]} · Fish 1</small></div></div> : <div className="association-options"><button className={sameFish === 'same' ? 'is-selected' : ''} onClick={() => onSameFish('same')}><span><Icon name="users" size={30} /></span><strong>Yes, same fish</strong><small>Associate both samples with Fish 1</small>{sameFish === 'same' && <Icon name="check" size={20} />}</button><button className={sameFish === 'different' ? 'is-selected' : ''} onClick={() => onSameFish('different')}><span><Icon name="database" size={30} /></span><strong>No, different fish</strong><small>Keep Fish 1 and Fish 2 independent</small>{sameFish === 'different' && <Icon name="check" size={20} />}</button></div>}<BottomBar onBack={onBack} primary={onContinue} primaryLabel="Continue" primaryDisabled={!single && !sameFish} /></div> }
function TutorialScreen({ samples, step, onStep, onContinue, onBack }: { samples: SampleType[]; step: number; onStep: (step: number) => void; onContinue: () => void; onBack: () => void }) { const items = [{ title: 'Pull out the tray', copy: 'Use the chamber handle and make sure the surface is clean.', image: '/assets/step 1.png' }, { title: 'Place each sample flat', copy: 'Center the selected sample inside the blue guide.', image: '/assets/step 2.png' }, { title: 'Push in and capture', copy: 'TunaEye saves each selected sample separately.', image: '/assets/step 3.png' }]; const current = items[step]; return <div className="screen-stack screen-stack--tutorial"><div className="tutorial-heading"><span className="eyebrow">Guided tutorial</span><h1>{current.title}</h1><p>{current.copy}</p><div className="tutorial-sample-chips">{samples.map(sample => <span key={sample}>{sample}</span>)}</div></div><div className="tutorial-stage"><div className="tutorial-stage__number">0{step + 1}</div><img className="tutorial-stage__image" src={current.image} alt={current.title} /><div className="tutorial-stage__callout"><Icon name="spark" size={20} /><span>{current.copy}</span></div></div><div className="tutorial-dots">{items.map((item, index) => <button key={item.title} className={step === index ? 'is-active' : ''} onClick={() => onStep(index)} aria-label={`Tutorial step ${index + 1}`} />)}</div><BottomBar onBack={onBack} primary={onContinue} primaryLabel={step < 2 ? 'Next' : 'Enter weight'} primaryIcon={step < 2 ? 'arrow' : 'scale'} /></div> }
function WeightScreen({ selected, sameFish, weights, onWeight, onContinue, onBack }: { selected: SampleType[]; sameFish: 'same' | 'different' | null; weights: Record<string, string>; onWeight: (fishId: string, value: string) => void; onContinue: () => void; onBack: () => void }) { const fishIds = Array.from(new Set(selected.map(sample => fishIdForSample({ sameFish } as never, sample)))); const valid = fishIds.every(id => Number(weights[id]) > 0); return <div className="screen-stack screen-stack--weight"><div className="weight-panel"><div className="weight-panel__copy"><span className="eyebrow">Step 4 · Manual weight entry</span><h1>Enter the fish weight{fishIds.length > 1 ? 's' : ''}.</h1><p>Use the external scale. TunaEye keeps each fish’s weight attached to the correct sample and receipt.</p><div className="manual-callout"><span className="manual-callout__icon"><Icon name="scale" size={24} /></span><span><strong>Weight entered manually</strong><small>{fishIds.length > 1 ? 'Two fish · two independent weights' : 'Required before results'}</small></span></div></div><div className="weight-entry weight-entry--multi">{fishIds.map(id => <label className="weight-row" key={id}><span>{id}<small>{selected.filter(sample => fishIdForSample({ sameFish } as never, sample) === id).join(' + ')}</small></span><div className="weight-input"><input inputMode="decimal" value={weights[id] ?? ''} onChange={event => onWeight(id, event.target.value.replace(/[^0-9.]/g, '').slice(0, 6))} placeholder="0.0" /><b>kg</b></div></label>)}<span className={`input-status ${valid ? 'is-valid' : ''}`}>{valid ? <><Icon name="check" size={16} />Ready to start capture</> : 'Enter a number greater than zero for each fish'}</span></div></div><BottomBar onBack={onBack} primary={onContinue} primaryLabel="Start capture" primaryIcon="camera" primaryDisabled={!valid} /></div> }
function CameraScreen({ sample, index, total, onCapture, onBack }: { sample: SampleType; index: number; total: number; onCapture: (image: string) => void; onBack: () => void }) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [cameraError, setCameraError] = useState('')
  const [cameras, setCameras] = useState<MediaDeviceInfo[]>([])
  const [cameraId, setCameraId] = useState('')
  useEffect(() => { let stream: MediaStream | undefined; setCameraError(''); navigator.mediaDevices?.getUserMedia({ video: cameraId ? { deviceId: { exact: cameraId } } : { facingMode: 'environment' }, audio: false }).then(async value => { stream = value; if (videoRef.current) videoRef.current.srcObject = value; const devices = (await navigator.mediaDevices.enumerateDevices()).filter(device => device.kind === 'videoinput'); setCameras(devices); if (!cameraId) setCameraId(value.getVideoTracks()[0]?.getSettings().deviceId ?? devices[0]?.deviceId ?? '') }).catch(() => setCameraError('Allow camera access in your browser, then reload this screen.')); return () => stream?.getTracks().forEach(track => track.stop()) }, [cameraId])
  const capture = () => { const video = videoRef.current; if (!video?.videoWidth) return; const canvas = document.createElement('canvas'); canvas.width = video.videoWidth; canvas.height = video.videoHeight; canvas.getContext('2d')?.drawImage(video, 0, 0); const image = canvas.toDataURL('image/jpeg', .9); capturedEvidence[sample] = image; onCapture(image) }
  return <div className="screen-stack screen-stack--camera"><div className="camera-layout"><div className="live-camera"><video ref={videoRef} autoPlay playsInline muted /><div className="target-corners"><i /><i /><i /><i /></div>{cameraError && <div className="camera-error"><Icon name="camera" size={28} />{cameraError}</div>}</div><aside className="camera-aside"><span className="eyebrow">Capture {index + 1} of {total}</span><div className="sample-context"><SampleArt sample={sample} /><span><strong>{sample}</strong><small>Live camera evidence</small></span></div><h1>Align the sample in the guide.</h1><p>Keep the surface still and fully visible. This sample remains linked to its fish.</p>{cameras.length > 0 && <label className="camera-selector"><span><Icon name="camera" size={18} />Camera source</span><select value={cameraId} onChange={event => setCameraId(event.target.value)}>{cameras.map((camera, cameraIndex) => <option key={camera.deviceId} value={camera.deviceId}>{camera.label || `Camera ${cameraIndex + 1}`}</option>)}</select><small>{cameras.length} camera{cameras.length === 1 ? '' : 's'} detected</small></label>}</aside></div><BottomBar onBack={onBack} onHelp={() => window.alert('Choose a camera, center the sample, then press Capture once.')} primary={capture} primaryLabel="Capture" primaryIcon="camera" primaryDisabled={Boolean(cameraError)} /></div>
}
function ReviewScreen({ sample, outcome, onRetake, onUse, onBack }: { sample: SampleType; outcome: DemoOutcome; onRetake: () => void; onUse: () => void; onBack: () => void }) { const valid = outcome === 'valid'; return <div className="screen-stack screen-stack--review"><div className="review-layout"><EvidenceFrame sample={sample} mode="sample" frozen /><aside className="review-aside"><span className={`review-badge review-badge--${outcome}`}>{valid ? <Icon name="check" size={17} /> : <Icon name="help" size={17} />}{valid ? 'Image looks good' : outcome === 'uncertain' ? 'Needs a closer look' : 'Image needs retake'}</span><h1>{valid ? 'Use this image?' : 'Let’s fix the image first.'}</h1><p>{valid ? `${sample} is centered, clear, and ready for demo analysis.` : outcome === 'uncertain' ? 'The view is usable, but the confidence may be too low for an automatic result.' : 'The sample is not positioned clearly enough inside the guide.'}</p><div className="review-note"><Icon name="shield" size={18} /><span>Saved locally after analysis · Demo mode</span></div></aside></div><BottomBar onBack={onBack} secondaryLabel="Retake" onSecondary={onRetake} primary={onUse} primaryLabel="Use this image" primaryIcon="arrow" /></div> }
function AnalysisScreen({ sample }: { sample: SampleType }) { return <div className="analysis-screen"><div className="analysis-screen__visual"><EvidenceFrame sample={sample} mode="sample" frozen /><div className="analysis-pulse"><span /><span /><span /></div></div><span className="eyebrow">Demo analysis · Local device</span><h1>Reading {sample.toLowerCase()}</h1><p>Checking color and clarity, then saving this evidence on the device.</p><StepRail active={1} /><div className="analysis-status"><span className="spinner" />Analyzing · no percentage estimate</div></div> }
function effectiveGrade(result: SampleResult | undefined): Grade | null { return result?.overrideGrade ?? result?.originalGrade ?? null }
function ResultImage({ sample }: { sample: SampleType }) { return <img className="result-sample-image" src={capturedEvidence[sample] ?? (sample === 'Sashibo core' ? '/assets/sashiboCoreFull.png' : '/assets/tailCutFull.png')} alt={`Captured ${sample}`} /> }
function IndividualResultScreen({ result, sample, weight, hasNext, onNext, onRetake, onOverride, onBack }: { result?: SampleResult; sample: SampleType; weight: string; hasNext: boolean; onNext: () => void; onRetake: () => void; onOverride: () => void; onBack: () => void }) { if (!result || result.status !== 'valid') { const uncertain = result?.status === 'uncertain'; return <div className="screen-stack screen-stack--recovery"><div className={`recovery-hero recovery-hero--${uncertain ? 'uncertain' : 'invalid'}`}><span className="recovery-hero__icon"><Icon name={uncertain ? 'help' : 'refresh'} size={34} /></span><span className="eyebrow">{uncertain ? 'Result needs review' : 'Image rejected'}</span><h1>{uncertain ? 'This result is uncertain.' : 'This image cannot be graded.'}</h1><p>{uncertain ? `${sample} is visible, but the confidence is too low to accept automatically.` : `${sample} needs a clearer view inside the blue guide. No grade was created.`}</p></div><div className="recovery-actions"><Button variant="secondary" onClick={onRetake} icon="refresh">Retake image</Button>{uncertain && <Button variant="ghost" onClick={onOverride} icon="shield">Expert review</Button>}</div><div className="recovery-note"><Icon name="shield" size={18} /><span>Original prediction is preserved. The sample stays linked to {result?.fishId ?? 'its fish'}.</span></div></div> } const grade = effectiveGrade(result); return <div className="screen-stack screen-stack--result"><div className="individual-result-layout"><div className="grade-hero"><span className="eyebrow">{result.overrideGrade ? 'Expert review applied' : 'Saved on device · Demo result'}</span><div className={`grade-letter grade-letter--${grade}`}>{grade}</div><h1>{sample} · Grade {grade}</h1><p>{result.overrideGrade ? `Expert decision replaces the original ${result.originalGrade ?? 'uncertain'} prediction.` : 'Strong color and clarity in the captured evidence.'}</p><div className="confidence"><div className="confidence__label"><span>Original model confidence</span><strong>{result.originalConfidence}%</strong></div><div className="confidence__track"><span style={{ width: `${result.originalConfidence}%` }} /></div></div><div className="result-badges"><span>{result.fishId}</span><span>{weight} kg</span>{result.overrideGrade && <span className="override-badge">Expert reviewed</span>}</div></div><div className="result-details"><ResultImage sample={sample} /><dl><div><dt>Sample type</dt><dd>{sample}</dd></div><div><dt>Associated fish</dt><dd>{result.fishId}</dd></div><div><dt>Weight</dt><dd>{weight} kg</dd></div><div><dt>Original prediction</dt><dd>{result.originalGrade ? `Grade ${result.originalGrade}` : 'Uncertain'}</dd></div><div><dt>Capture</dt><dd>Saved on device</dd></div><div><dt>Decision</dt><dd>{result.overrideGrade ? `Expert Grade ${result.overrideGrade}` : 'Model result'}</dd></div></dl></div></div><div className="result-actions"><Button variant="secondary" onClick={onOverride} icon="settings">Manual override</Button><Button variant="ghost" onClick={onBack} icon="back">Results later</Button><Button onClick={onNext} icon="arrow">{hasNext ? 'Next sample' : 'View results overview'}</Button></div></div> }
function OverviewScreen({ selected, results, sameFish, onOverride, onPrint, onBack }: { selected: SampleType[]; results: Partial<Record<SampleType, SampleResult>>; sameFish: 'same' | 'different' | null; onOverride: (sample: SampleType) => void; onPrint: () => void; onBack: () => void }) { const complete = selected.every(sample => results[sample]); const validResults = selected.map(sample => results[sample]).filter((result): result is SampleResult => Boolean(result?.originalConfidence)); const combinedConfidence = validResults.length > 1 ? Math.round(validResults.reduce((sum, result) => sum + (result.originalConfidence ?? 0), 0) / validResults.length) : null; return <div className="screen-stack screen-stack--overview"><div className="section-heading"><span className="eyebrow">Results overview · {sameFish === 'different' ? 'Independent fish' : 'Same fish'}</span><h1>Review every sample before printing.</h1><p>Original model outputs stay visible next to any manual decision. Nothing is averaged across different fish.</p></div><div className="overview-cards">{selected.map(sample => { const result = results[sample]; const grade = effectiveGrade(result); return <div className="overview-card" key={sample}><div className="overview-card__head"><ResultImage sample={sample} /><div><span className="eyebrow">{result?.fishId ?? 'Pending fish'}</span><h2>{sample}</h2><span className={`status-label status-label--${result?.status ?? 'invalid'}`}>{result?.status === 'valid' ? `Grade ${grade}` : result?.status === 'uncertain' ? 'Uncertain' : 'Not graded'}</span></div></div><div className="overview-card__stats"><span><small>Confidence</small><strong>{result?.originalConfidence ? `${result.originalConfidence}%` : '—'}</strong></span><span><small>Weight</small><strong>{result ? `${result.fishId} linked` : '—'}</strong></span></div><Button variant="ghost" onClick={() => onOverride(sample)} icon="settings">Manual override</Button></div> })}</div>{selected.length > 1 && <div className={`combined-panel combined-panel--${sameFish === 'same' ? 'same' : 'different'}`}><span className="combined-panel__icon"><Icon name={sameFish === 'same' ? 'users' : 'database'} size={24} /></span><div><span className="eyebrow">{sameFish === 'same' ? 'Same-fish comparison' : 'Independent assessments'}</span><h2>{sameFish === 'same' ? 'Combined assessment · expert confirmation' : 'Two separate fish · no shared grade'}</h2><p>{sameFish === 'same' ? `Both samples remain visible together. Compatible confidence average: ${combinedConfidence ?? '—'}%. No categorical grades are averaged in this demo.` : 'Each sample keeps its own fish, weight, grade, confidence, override, and receipt copy.'}</p></div></div>}<BottomBar onBack={onBack} primary={onPrint} primaryLabel={complete ? 'Print separate copies' : 'Finish remaining samples'} primaryIcon={complete ? 'printer' : 'arrow'} primaryDisabled={!complete} /></div> }
function OverrideModal({ sample, result, onSave, onClose }: { sample: SampleType; result?: SampleResult; onSave: (grade: Grade, reason: string) => void; onClose: () => void }) { const [grade, setGrade] = useState<Grade>(result?.overrideGrade ?? result?.originalGrade ?? 'A'); const [reason, setReason] = useState(result?.overrideReason ?? ''); return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label="Manual override"><div className="modal-card override-modal"><div className="modal-card__header"><div><span className="eyebrow">Expert decision</span><h2>Manual override · {sample}</h2></div><button className="icon-button" aria-label="Close manual override" onClick={onClose}>×</button></div><p>Original model prediction: <strong>Grade {result?.originalGrade ?? '—'} · {result?.originalConfidence ?? '—'}% confidence</strong></p><span className="field-label">Select the final grade</span><div className="override-grades">{(['A', 'B', 'C'] as Grade[]).map(item => <button key={item} className={grade === item ? 'is-selected' : ''} onClick={() => setGrade(item)}>Grade {item}</button>)}</div><label className="field-label">Reason <textarea value={reason} onChange={event => setReason(event.target.value)} placeholder="Optional note for the record" rows={3} /></label><div className="override-modal__actions"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button onClick={() => onSave(grade, reason)} icon="check">Save override</Button></div></div></div> }
function PrintScreen({ samples, results, printIndex, printed, printing, onPrint, onSkip, onBack }: { samples: SampleType[]; results: Partial<Record<SampleType, SampleResult>>; printIndex: number; printed: SampleType[]; printing: boolean; onPrint: () => void; onSkip: () => void; onBack: () => void }) { const sample = samples[printIndex] ?? samples[0]; const result = results[sample]; const grade = effectiveGrade(result); return <div className="screen-stack screen-stack--print"><div className="print-layout"><div className="print-copy"><span className="eyebrow">Print {printIndex + 1} of {samples.length} · Demo printer</span><h1>{printed.length ? 'Print the next result.' : 'Print separate grading records.'}</h1><p>Each copy keeps its sample type, associated fish, weight, grade, confidence, and any manual override.</p><div className="print-queue">{samples.map((item, index) => <div key={item} className={printed.includes(item) ? 'is-printed' : index === printIndex ? 'is-current' : ''}><span>{printed.includes(item) ? <Icon name="check" size={16} /> : index + 1}</span><strong>{item}</strong><small>{printed.includes(item) ? 'Printed' : index === printIndex ? 'Ready now' : 'Next copy'}</small></div>)}</div></div><div className="receipt"><div className="receipt__top"><BrandMark compact /><span>GRADING RECORD</span></div><div className="receipt__sample"><span>{sample}</span><strong>{result?.fishId ?? 'Fish'}</strong></div><div className="receipt__grade"><span>GRADE</span><strong>{grade ?? '—'}</strong><small>{result?.originalConfidence ? `${result.originalConfidence}% original confidence` : 'No automatic grade'}</small></div><div className="receipt__rows"><div><span>Weight</span><strong>{result ? `${result.fishId} linked` : '—'}</strong></div><div><span>Decision</span><strong>{result?.overrideGrade ? `Manual Grade ${result.overrideGrade}` : 'Model result'}</strong></div><div><span>Record</span><strong>TE-261005-{String(14 + printIndex).padStart(3, '0')}</strong></div></div><div className="receipt__footer">TunaEye · Demo receipt<br />Saved on device</div></div></div><BottomBar onBack={onBack} secondaryLabel="Skip printing" onSecondary={onSkip} primary={onPrint} primaryLabel={printing ? 'Printing…' : `Print ${sample}`} primaryIcon="printer" primaryDisabled={printing} /></div> }
function CompleteScreen({ printed, onAgain, onHome }: { printed: SampleType[]; onAgain: () => void; onHome: () => void }) { return <div className="complete-screen"><div className="complete-screen__check"><Icon name="check" size={42} /></div><span className="eyebrow">Done</span><h1>Results printed.</h1><p>{printed.length > 1 ? 'Separate copies were created for each selected sample.' : 'The grading record is saved on this device.'}</p><div className="complete-print-list">{printed.map(sample => <span key={sample}><Icon name="check" size={16} />{sample}</span>)}</div><div className="complete-screen__meta"><span className="status-dot" />Ready for the next grader</div><div className="complete-screen__actions"><Button onClick={onAgain} icon="refresh">Grade another</Button><Button variant="ghost" onClick={onHome} icon="home">Return home</Button></div><span className="auto-reset-note">Auto-reset is ready after inactivity</span></div> }

function App() {
  const [session, dispatch] = useReducer(reducer, initialSession)
  const [tutorialOpen, setTutorialOpen] = useState(false)
  const [legalKind, setLegalKind] = useState<'terms' | 'privacy' | null>(null)
  const [overrideTarget, setOverrideTarget] = useState<SampleType | null>(null)
  const [isCapturing, setIsCapturing] = useState(false)
  const [isPrinting, setIsPrinting] = useState(false)
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null)
  const [installed, setInstalled] = useState(() => window.matchMedia('(display-mode: standalone)').matches)
  const [currentPathScreen] = useState<Screen>(() => screenForPath(window.location.pathname))
  useEffect(() => { const beforeInstall = (event: Event) => { event.preventDefault(); setInstallPrompt(event as BeforeInstallPromptEvent) }; const appInstalled = () => { setInstalled(true); setInstallPrompt(null) }; window.addEventListener('beforeinstallprompt', beforeInstall); window.addEventListener('appinstalled', appInstalled); return () => { window.removeEventListener('beforeinstallprompt', beforeInstall); window.removeEventListener('appinstalled', appInstalled) } }, [])
  useEffect(() => { if (currentPathScreen !== 'welcome') dispatch({ type: 'navigate', screen: currentPathScreen }); const onPopState = () => dispatch({ type: 'navigate', screen: screenForPath(window.location.pathname) }); window.addEventListener('popstate', onPopState); return () => window.removeEventListener('popstate', onPopState) }, [currentPathScreen])
  const go = useCallback((screen: Screen) => { dispatch({ type: 'navigate', screen }); window.history.pushState({}, '', pathForScreen(screen)) }, [])
  const goHome = useCallback(() => { Object.keys(capturedEvidence).forEach(key => delete capturedEvidence[key as SampleType]); dispatch({ type: 'reset' }); window.history.pushState({}, '', '/') }, [])
  const back = () => { const previous: Partial<Record<Screen, Screen>> = { 'select-role': 'welcome', admin: 'select-role', 'admin-dashboard': 'select-role', grader: 'select-role', sample: 'grader', association: 'sample', tutorial: selected.length === 1 ? 'sample' : 'association', weight: 'tutorial', camera: 'weight', review: 'camera', analysis: 'review', 'individual-result': 'review', overview: 'individual-result', print: 'overview' }; const target = previous[session.screen]; target ? go(target) : goHome() }
  const selected = session.selectedSamples.length ? session.selectedSamples : ['Sashibo core'] as SampleType[]
  const sample = currentSample(session)
  const currentResult = session.results[sample]
  const capture = () => { if (isCapturing) return; setIsCapturing(true); window.setTimeout(() => { dispatch({ type: 'captured' }); setIsCapturing(false) }, 850) }
  useEffect(() => { if (session.screen !== 'analysis') return; const timeout = window.setTimeout(() => dispatch({ type: 'finishAnalysis', outcome: session.demoOutcome }), 1700); return () => window.clearTimeout(timeout) }, [session.screen, session.demoOutcome])
  useEffect(() => { if (session.screen !== 'complete') return; const timeout = window.setTimeout(() => goHome(), 30000); return () => window.clearTimeout(timeout) }, [session.screen, goHome])
  const openRole = (role: Role) => { dispatch({ type: 'setRole', role }); go(role === 'admin' ? 'admin' : 'grader') }
  const fishWeights = session.fishWeights
  const print = () => { if (isPrinting) return; setIsPrinting(true); window.print(); dispatch({ type: 'printed', sample: selected[session.printIndex] ?? selected[0] }); setIsPrinting(false); if (session.printIndex + 1 >= selected.length) go('complete') }
  const installApp = async () => { if (installed) return; if (!installPrompt) { window.alert('To install TunaEye, open your browser menu and choose “Install app” or “Add to Home Screen”.'); return } await installPrompt.prompt(); const choice = await installPrompt.userChoice; if (choice.outcome === 'accepted') setInstalled(true); setInstallPrompt(null) }
  const renderScreen = () => {
    switch (session.screen) {
      case 'welcome': return <WelcomeScreen onStart={() => go('select-role')} onInstall={installApp} installed={installed} onTutorial={() => setTutorialOpen(true)} />
      case 'select-role': return <SelectRoleScreen onRole={openRole} onTutorial={() => setTutorialOpen(true)} onBack={back} />
      case 'admin': return <AdminPinScreen value={session.adminPin} error={session.adminError} onChange={value => dispatch({ type: 'setAdminPin', value })} onContinue={() => session.adminPin === DEMO_ADMIN_PIN ? dispatch({ type: 'adminAuthenticated' }) : dispatch({ type: 'adminError', message: 'Incorrect PIN. Use the demo PIN 1234.' })} onBack={back} />
      case 'admin-dashboard': return <AdminDashboard onExit={goHome} />
      case 'grader': return <GraderEntryScreen name={session.graderName} remember={session.rememberName} onName={value => dispatch({ type: 'setGraderName', value })} onRemember={value => dispatch({ type: 'setRememberName', value })} onContinue={() => go('sample')} onBack={back} onLegal={setLegalKind} />
      case 'sample': return <SampleScreen selected={selected} onSelect={samples => dispatch({ type: 'setSamples', samples })} onContinue={() => { if (selected.length === 1) { dispatch({ type: 'setSameFish', value: 'same' }); go('tutorial') } else go('association') }} onBack={back} />
      case 'association': return <AssociationScreen samples={selected} sameFish={session.sameFish} onSameFish={value => dispatch({ type: 'setSameFish', value })} onContinue={() => { if (selected.length === 1) dispatch({ type: 'setSameFish', value: 'same' }); go('tutorial') }} onBack={back} />
      case 'tutorial': return <TutorialScreen samples={selected} step={session.tutorialStep} onStep={step => dispatch({ type: 'setTutorialStep', step })} onContinue={() => session.tutorialStep < 2 ? dispatch({ type: 'setTutorialStep', step: session.tutorialStep + 1 }) : go('weight')} onBack={back} />
      case 'weight': return <WeightScreen selected={selected} sameFish={session.sameFish} weights={fishWeights} onWeight={(fishId, value) => dispatch({ type: 'setFishWeight', fishId, value })} onContinue={() => go('camera')} onBack={back} />
      case 'camera': return <CameraScreen sample={sample} index={session.currentSampleIndex} total={selected.length} onCapture={capture} onBack={back} />
      case 'review': return <ReviewScreen sample={sample} outcome={session.demoOutcome} onRetake={() => go('camera')} onUse={() => dispatch({ type: 'startAnalysis' })} onBack={back} />
      case 'analysis': return <AnalysisScreen sample={sample} />
      case 'individual-result': return <IndividualResultScreen result={currentResult} sample={sample} weight={weightForSample(session, sample)} hasNext={session.currentSampleIndex < selected.length - 1} onNext={() => session.currentSampleIndex < selected.length - 1 ? dispatch({ type: 'nextSample' }) : go('overview')} onRetake={() => go('camera')} onOverride={() => setOverrideTarget(sample)} onBack={back} />
      case 'overview': return <OverviewScreen selected={selected} results={session.results} sameFish={session.sameFish} onOverride={setOverrideTarget} onPrint={() => dispatch({ type: 'startPrinting' })} onBack={back} />
      case 'print': return <PrintScreen samples={selected} results={session.results} printIndex={session.printIndex} printed={session.printedSamples} printing={isPrinting} onPrint={print} onSkip={() => go('complete')} onBack={back} />
      case 'complete': return <CompleteScreen printed={session.printedSamples} onAgain={goHome} onHome={goHome} />
    }
  }
  const showShell = !['welcome', 'complete'].includes(session.screen)
  return <div className="app-shell">{showShell && <TopBar screen={session.screen} onHome={goHome} />}<main className={`app-main app-main--${session.screen}`}>{renderScreen()}</main>{tutorialOpen && <TutorialModal onClose={() => setTutorialOpen(false)} />}{legalKind && <LegalModal kind={legalKind} onClose={() => setLegalKind(null)} />}{overrideTarget && <OverrideModal sample={overrideTarget} result={session.results[overrideTarget]} onClose={() => setOverrideTarget(null)} onSave={(grade, reason) => { dispatch({ type: 'setOverride', sample: overrideTarget, grade, reason }); setOverrideTarget(null) }} />}{isCapturing && <div className="capture-toast"><span className="capture-toast__ring"><Icon name="camera" size={22} /></span><span><strong>Capturing image</strong><small>Hold still for a moment</small></span></div>}{isPrinting && <div className="capture-toast"><span className="capture-toast__ring"><Icon name="printer" size={22} /></span><span><strong>Printing result</strong><small>Please wait · demo printer</small></span></div>}</div>
}

export default App
